import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter

fun check(n: Int): Boolean {
    var sum = 0
    var num = n
    while (num > 0) {
        sum += num % 10
        num /= 10
    }
    return sum == 10
}

fun solution(reader: BufferedReader, writer: PrintWriter) {
    val k = reader.readLine()?.toInt() ?: 0
    var count = k
    var i = 19
    while (count > 0) {
        if (check(i)) {
            count--
        }
        if (count == 0) {
            writer.println(i)
            return
        }
        i++
    }
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val writer = PrintWriter(System.out)
    try {
        solution(reader, writer)
    } finally {
        writer.flush()
    }
}

